import "fmt"

// Priority represents the severity level of a notification.
type Priority int

const (
	PriorityUnknown Priority = iota
	PriorityLow
	PriorityMedium
	PriorityHigh
	PriorityCritical
)

// ValidPriorityValues lists the accepted priority strings.
var ValidPriorityValues = []string{"low", "medium", "high", "critical"}

func (p Priority) String() string {
	switch p {
	case PriorityLow:
		return "low"
	case PriorityMedium:
		return "medium"
	case PriorityHigh:
		return "high"
	case PriorityCritical:
		return "critical"
	default:
		return "unknown"
	}
}

// ParsePriority converts a string to a Priority value.
// Returns PriorityUnknown and an error if the string is not valid.
func ParsePriority(s string) (Priority, error) {
	switch s {
	case "low":
		return PriorityLow, nil
	case "medium":
		return PriorityMedium, nil
	case "high":
		return PriorityHigh, nil
	case "critical":
		return PriorityCritical, nil
	default:
		return PriorityUnknown, fmt.Errorf("invalid priority: %q (valid: %v)", s, ValidPriorityValues)
	}
}

