func TestCreateNotificationRequest_Validate(t *testing.T) {
	tests := []struct {
		name    string
		req     domain.CreateNotificationRequest
		wantErr bool
		errMsg  string
	}{
		{
			name:    "missing message field",
			req:     domain.CreateNotificationRequest{Message: "", Priority: "low"},
			wantErr: true,
			errMsg:  "message is required",
		},
		{
			name:    "missing priority field",
			req:     domain.CreateNotificationRequest{Message: "Test", Priority: ""},
			wantErr: true,
			errMsg:  "priority is required",
		},
		{
			name:    "both fields missing",
			req:     domain.CreateNotificationRequest{Message: "", Priority: ""},
			wantErr: true,
			errMsg:  "message is required",
		},
		{
			name:    "all fields present and valid",
			req:     domain.CreateNotificationRequest{Message: "Test", Priority: "low"},
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.req.Validate()
			if tt.wantErr {
				if err == nil {
					t.Fatal("expected error, got nil")
				}
				if err.Error() != tt.errMsg {
					t.Errorf("expected error %q, got %q", tt.errMsg, err.Error())
				}
				var valErr *domain.ValidationError
				if !asValidationError(err, &valErr) {
					t.Errorf("expected *ValidationError, got %T", err)
				}
			} else {
				if err != nil {
					t.Errorf("unexpected error: %v", err)
				}
			}
		})
	}
}

func asValidationError(err error, target **domain.ValidationError) bool {
	if err == nil {
		return false
	}
	e, ok := err.(*domain.ValidationError)
	if ok {
		*target = e
	}
	return ok
}

