func TestService_CreateNotification_Success(t *testing.T) {
	ctx := context.Background()

	var savedNotif *domain.Notification
	var savedEvent *domain.OutboxEvent

	repo := &fakeRepo{
		createFn: func(ctx context.Context, n *domain.Notification, evt *domain.OutboxEvent) error {
			savedNotif = n
			savedEvent = evt
			return nil
		},
	}

	svc := application.NewService(repo)

	req := domain.CreateNotificationRequest{Message: "Hello world", Priority: "high"}
	result, err := svc.CreateNotification(ctx, req)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
