import "fmt"

type Severity string

const (
	SeverityLow      Severity = "low"
	SeverityMedium   Severity = "medium"
	SeverityHigh     Severity = "high"
	SeverityCritical Severity = "critical"
)

type Environment string

const (
	EnvDev     Environment = "dev"
	EnvStaging Environment = "staging"
	EnvProd    Environment = "prod"
)

type ApprovalGateStatus string

const (
	GateStatusBlocked ApprovalGateStatus = "blocked"
	GateStatusPassed  ApprovalGateStatus = "passed"
	GateStatusPending ApprovalGateStatus = "pending"
)

type PolicyRule struct {
	ID          string      `json:"id"`
	Severity    Severity    `json:"severity"`
	Service     string      `json:"service"`
	Environment Environment `json:"environment"`
	Description string      `json:"description"`
	Remediation string      `json:"remediation"`
	BlockMerge  bool        `json:"block_merge"`
}

type RequiredApprovers struct {
	Severity        Severity    `json:"severity"`
	AffectedService string      `json:"affected_service"`
	Environment     Environment `json:"environment"`
	Approvers       []string    `json:"approvers"`
}

type PolicyViolation struct {
	RuleID      string   `json:"rule_id"`
	Message     string   `json:"message"`
	Remediation string   `json:"remediation"`
	Severity    Severity `json:"severity"`
}

type EvaluationResult struct {
	Violations        []PolicyViolation  `json:"violations"`
	RequiredApprovers RequiredApprovers  `json:"required_approvers"`
	MergeBlocked      bool               `json:"merge_blocked"`
	GateStatus        ApprovalGateStatus `json:"gate_status"`
}

type Event struct {
	Type   string      `json:"type"`
	Status string      `json:"status"`
	PRID   int         `json:"pr_id"`
	Data   interface{} `json:"data,omitempty"`
}

type PolicyEngine struct {
	rules []PolicyRule
}

func NewPolicyEngine(rules []PolicyRule) *PolicyEngine {
	return &PolicyEngine{rules: rules}
}

func (e *PolicyEngine) GetRules() []PolicyRule {
	return e.rules
}

func (e *PolicyEngine) EvaluatePR(prID int, service string, env Environment, severity Severity) (*EvaluationResult, error) {
	if service == "" {
		return nil, fmt.Errorf("service cannot be empty")
	}
	if env == "" {
		return nil, fmt.Errorf("environment cannot be empty")
	}
	violations := e.findViolations(service, env, severity)
	approvers := e.determineApprovers(service, env, severity)
	mergeBlocked := false
	gateStatus := GateStatusPassed
	for _, v := range violations {
		if v.Severity == SeverityCritical || v.Severity == SeverityHigh {
			mergeBlocked = true
			gateStatus = GateStatusBlocked
			break
		}
	}
	return &EvaluationResult{
		Violations:        violations,
		RequiredApprovers: approvers,
		MergeBlocked:      mergeBlocked,
		GateStatus:        gateStatus,
	}, nil
}

func (e *PolicyEngine) PublishApprovalGateStatus(prID int, status ApprovalGateStatus, violations []PolicyViolation) Event {
	return Event{
		Type:   "approval_gate_status",
		Status: string(status),
		PRID:   prID,
		Data:   map[string]interface{}{"violations": violations},
	}
}

func (e *PolicyEngine) GenerateViolationMessage(violation PolicyViolation) string {
	return fmt.Sprintf("Policy Violation: %s\n\nRule: %s\nSeverity: %s\n\nMessage: %s\n\nRemediation Guidance:\n%s", violation.RuleID, violation.RuleID, violation.Severity, violation.Message, violation.Remediation)
}

func (e *PolicyEngine) findViolations(service string, env Environment, severity Severity) []PolicyViolation {
	var violations []PolicyViolation
	for _, rule := range e.rules {
		if ruleMatches(rule, service, env, severity) {
			violations = append(violations, PolicyViolation{RuleID: rule.ID, Message: rule.Description, Remediation: rule.Remediation, Severity: rule.Severity})
		}
	}
	return violations
}

func (e *PolicyEngine) determineApprovers(service string, env Environment, severity Severity) RequiredApprovers {
	return RequiredApprovers{Severity: severity, AffectedService: service, Environment: env, Approvers: e.getApproversForLevel(env, severity)}
}

func (e *PolicyEngine) getApproversForLevel(env Environment, severity Severity) []string {
	if env == EnvProd {
		if severity == SeverityCritical || severity == SeverityHigh {
			return []string{"change-advisory-board", "platform-lead", "security-team"}
		}
		return []string{"platform-lead"}
	}
	if env == EnvStaging {
		if severity == SeverityCritical {
			return []string{"platform-lead", "senior-engineer"}
		}
		return []string{"senior-engineer"}
	}
	return []string{"team-lead"}
}

func ruleMatches(rule PolicyRule, service string, env Environment, severity Severity) bool {
	if rule.Environment != "" && rule.Environment != env { return false }
	if rule.Service != "" && rule.Service != service { return false }
	if rule.Severity != "" && rule.Severity != severity { return false }
	return true
}
