func TestRuleMatches_ExactMatch(t *testing.T) {
	t.Parallel()
	rule := PolicyRule{ID: "test-rule", Severity: SeverityCritical, Service: "payment-gateway", Environment: EnvProd}
	assert.True(t, ruleMatches(rule, "payment-gateway", EnvProd, SeverityCritical))
}

func TestRuleMatches_WrongService(t *testing.T) {
