', 'terraform/gcp/us-central1/main.tf': '# ----------------------------------------------------------------------
# OpenClaw - GCP GKE Cluster (us-central1)
# Terraform / OpenTofu Configuration
# ----------------------------------------------------------------------

terraform {
  required_version = ">= 1.6.0"

  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.25"
    }
    google-beta = {
      source  = "hashicorp/google-beta"
      version = "~> 5.25"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.27"
    }
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.12"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }

  backend "gcs" {
    bucket = "openclaw-terraform-state-gcp"
    prefix = "gke/us-central1"
  }
}

provider "google" {
  project = var.gcp_project_id
  region  = var.gcp_region
}

provider "google-beta" {
  project = var.gcp_project_id
  region  = var.gcp_region
}

# ----------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------
resource "google_compute_network" "vpc" {
  name                    = "${var.cluster_name}-vpc"
  auto_create_subnetworks = false
  routing_mode            = "REGIONAL"
}

resource "google_compute_subnetwork" "subnet" {
  name          = "${var.cluster_name}-subnet"
  ip_cidr_range = "10.2.0.0/16"
  region        = var.gcp_region
  network       = google_compute_network.vpc.id

  secondary_ip_range = [
    {
      range_name    = "pods"
      ip_cidr_range = "10.20.0.0/14"
    },
    {
      range_name    = "services"
      ip_cidr_range = "10.24.0.0/16"
    },
  ]

  private_ip_google_access = true
}

resource "google_compute_router" "router" {
  name    = "${var.cluster_name}-router"
  region  = var.gcp_region
  network = google_compute_network.vpc.id
}

resource "google_compute_router_nat" "nat" {
  name                               = "${var.cluster_name}-nat"
  router                             = google_compute_router.router.name
  region                             = var.gcp_region
  nat_ip_allocate_option             = "AUTO_ONLY"
  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"
}

# ----------------------------------------------------------------------
# GKE Cluster
# ----------------------------------------------------------------------
resource "google_service_account" "gke_sa" {
  account_id   = "${replace(var.cluster_name, "-", "")}-sa"
  display_name = "GKE Service Account for ${var.cluster_name}"
}

resource "google_container_cluster" "primary" {
  provider = google-beta

  name     = var.cluster_name
  location = var.gcp_region

  network    = google_compute_network.vpc.id
  subnetwork = google_compute_subnetwork.subnet.id

  # Remove default node pool
  initial_node_count = 1
  remove_default_node_pool = true

  # Networking
  networking_mode = "VPC_NATIVE"
  ip_allocation_policy {
    cluster_secondary_range_name  = "pods"
    services_secondary_range_name = "services"
  }

  # Private cluster
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Workload Identity
  workload_identity_config {
    workload_pool = "${var.gcp_project_id}.svc.id.goog"
  }

  # Vertical Pod Autoscaling
  vertical_pod_autoscaling {
    enabled = true
  }

  # Release channel
  release_channel {
    channel = "REGULAR"
  }

  # Addons
  addons_config {
    horizontal_pod_autoscaling {
      disabled = false
    }
    http_load_balancing {
      disabled = false
    }
    network_policy_config {
      disabled = false
    }
    gce_persistent_disk_csi_driver_config {
      enabled = true
    }
  }

  # Network policy (Calico)
  network_policy {
    enabled  = true
    provider = "CALICO"
  }

  # Maintenance window
  maintenance_policy {
    recurring_window {
      start_time = "2024-01-01T02:00:00Z"
      end_time   = "2024-01-01T06:00:00Z"
      recurrence = "FREQ=WEEKLY;BYDAY=SA,SU"
    }
  }

  # Cluster security
  pod_security_policy_config {
    enabled = false
  }

  master_auth {
    client_certificate_config {
      issue_client_certificate = false
    }
  }

  # Binary Authorization
  binary_authorization {
    evaluation_mode = "PROJECT_SINGLETON_POLICY_ENFORCE"
  }

  # Shielded Nodes
  enable_shielded_nodes = true

  # Cost management
  resource_usage_export_config {
    enable_network_egress_metering       = true
    enable_resource_consumption_metering = true
    bigquery_destination {
      dataset_id = "${var.cluster_name}_usage"
    }
  }

  depends_on = [
    google_compute_subnetwork.subnet,
    google_compute_router_nat.nat,
  ]
}

# ----------------------------------------------------------------------
# Node Pools
# ----------------------------------------------------------------------
resource "google_container_node_pool" "core" {
  name       = "${var.cluster_name}-core"
  location   = var.gcp_region
  cluster    = google_container_cluster.primary.name
  node_count = 3

  node_config {
    machine_type = "e2-standard-4"
    disk_size_gb = 50
    disk_type    = "pd-ssd"
    image_type   = "COS_CONTAINERD"

    service_account = google_service_account.gke_sa.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform",
    ]

    labels = {
      workload-type = "core"
    }

    tags = ["gke-node", "${var.cluster_name}"]

    shielded_instance_config {
      enable_secure_boot          = true
      enable_integrity_monitoring = true
    }

    workload_metadata_config {
      mode = "GKE_METADATA"
    }
  }

  autoscaling {
    min_node_count = 2
    max_node_count = 10
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }
}

resource "google_container_node_pool" "compute" {
  name       = "${var.cluster_name}-compute"
  location   = var.gcp_region
  cluster    = google_container_cluster.primary.name
  node_count = 0

  node_config {
    machine_type = "c2-standard-8"
    disk_size_gb = 100
    disk_type    = "pd-ssd"
    image_type   = "COS_CONTAINERD"

    service_account = google_service_account.gke_sa.email
    oauth_scopes = ["https://www.googleapis.com/auth/cloud-platform"]

    labels = { workload-type = "compute" }
    tags   = ["gke-node", "${var.cluster_name}"]

    shielded_instance_config {
      enable_secure_boot          = true
      enable_integrity_monitoring = true
    }
  }

  autoscaling {
    min_node_count = 0
    max_node_count = 20
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }
}

# ----------------------------------------------------------------------
# Workload Identity Bindings
# ----------------------------------------------------------------------
resource "google_service_account_iam_member" "workload_identity" {
  for_each = toset([
    "backend", "board-api", "gitops-service", "finops-service",
    "triage-service", "workspace-service"
  ])

  service_account_id = google_service_account.gke_sa.name
  role               = "roles/iam.workloadIdentityUser"
  member             = "serviceAccount:${var.gcp_project_id}.svc.id.goog[openclaw/${each.key}]"
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------
output "cluster_name" {
  value = google_container_cluster.primary.name
}

output "cluster_endpoint" {
  value     = google_container_cluster.primary.endpoint
  sensitive = true
}

output "cluster_ca_certificate" {
  value     = google_container_cluster.primary.master_auth[0].cluster_ca_certificate
  sensitive = true
}

output "workload_pool" {
  value = google_container_cluster.primary.workload_identity_config[0].workload_pool
}

output "region" {
  value = var.gcp_region
}
