// =============================================================================
// GITOPS-01: Type Definitions
// Core types for the Automated Incident Response via GitOps PRs workflow
// =============================================================================

export type PRStatus =
  | 'draft'
  | 'ci-in-progress'
  | 'ci-failed'
  | 'policy-check'
  | 'approvals-pending'
  | 'merged'
  | 'reverted'
  | 'cancelled'

export type StepKey = 'draft' | 'ci' | 'policy' | 'approvals' | 'merged'

export type StepStatus = 'pending' | 'active' | 'completed' | 'failed'

export type IncidentSeverity = 'P0' | 'P1' | 'P2' | 'P3'

export type Phase =
  | 'idle'
  | 'preview'
  | 'creating'
  | 'created'
  | 'ci-running'
  | 'ci-failed'
  | 'policy-check'
  | 'awaiting-approval'
  | 'merged'
  | 'failed'
  | 'cancelled'

export interface TimelineStepData {
  key: StepKey
  label: string
  status: StepStatus
  timestamp: string | null
  description: string | null
}

export interface PRChange {
  path: string
  changeType: 'added' | 'modified' | 'deleted'
  diff: string
}

export interface CIFailureDetail {
  check: string
  status: 'failed' | 'skipped' | 'passed'
  logUrl: string | null
}

export interface PRData {
  prNumber: number
  prUrl: string
  title: string
  description: string
  createdAt: string
  targetBranch: string
}

export interface CIFailureData {
  message: string
  failureDetails: CIFailureDetail[]
  prNumber: number | null
}

/**
 * Maps a Phase to the timeline step statuses.
 * 'completed' for steps before current phase,
 * 'active' for current phase step,
 * 'pending' for remaining steps.
 */
export function deriveTimelineSteps(phase: Phase): TimelineStepData[] {
  const stepOrder: { key: StepKey; label: string }[] = [
    { key: 'draft', label: 'Draft' },
    { key: 'ci', label: 'CI Checks' },
    { key: 'policy', label: 'Policy Check' },
    { key: 'approvals', label: 'Approvals' },
    { key: 'merged', label: 'Merged' },
  ]

  const phaseStepMap: Record<Phase, number> = {
    idle: -1,
    preview: 0,
    creating: 0,
    created: 0,
    'ci-running': 1,
    'ci-failed': 1,
    'policy-check': 2,
    'awaiting-approval': 3,
    merged: 4,
    failed: -1,
    cancelled: -2,
  }

  const currentIdx = phaseStepMap[phase] ?? -1

  return stepOrder.map((step, index) => {
    let status: StepStatus = 'pending'

    if (phase === 'cancelled') {
      status = 'pending'
    } else if (phase === 'failed' && index === 0) {
      status = 'failed'
    } else if (index < currentIdx) {
      status = 'completed'
    } else if (index === currentIdx) {
      if (phase === 'ci-failed') {
        status = 'failed'
      } else {
        status = 'active'
      }
    }

    return {
      key: step.key,
      label: step.label,
      status,
      timestamp: null,
      description: null,
    }
  })
}


