// =============================================================================
// GITOPS-01: Real-time Event Stream Composable
// SSE-based event stream with exponential backoff reconnection
// =============================================================================

import { ref, shallowRef, onMounted, onBeforeUnmount, type Ref, type ShallowRef } from 'vue'

export type ConnectionStatus = 'connecting' | 'connected' | 'disconnected' | 'error'

export interface GitOpsStreamEvent {
  type: 'pr-status-update' | 'pr-created' | 'ci-status-update' | 'policy-status-update' | 'pr-merged' | 'error'
  data: Record<string, unknown>
}

export interface UseGitOpsEventStreamOptions {
  incidentId: string
  url?: string
  initialBackoffMs?: number
  maxBackoffMs?: number
}

export interface UseGitOpsEventStreamReturn {
  connectionStatus: Ref<ConnectionStatus>
  lastEvent: ShallowRef<GitOpsStreamEvent | null>
  eventTimestamp: Ref<number>
  connect: () => void
  disconnect: () => void
}

const DEFAULT_URL = '/api/v1/gitops/events'
const INITIAL_BACKOFF = 1000
const MAX_BACKOFF = 30000

/**
 * Composable that connects to an SSE endpoint and provides real-time
 * GitOps PR status updates with automatic exponential backoff reconnection.
 */
export function useGitOpsEventStream(
  options: UseGitOpsEventStreamOptions
): UseGitOpsEventStreamReturn {
  const { incidentId, url = DEFAULT_URL, initialBackoffMs = INITIAL_BACKOFF, maxBackoffMs = MAX_BACKOFF } = options

  const connectionStatus = ref<ConnectionStatus>('disconnected')
  const lastEvent = shallowRef<GitOpsStreamEvent | null>(null)
  const eventTimestamp = ref<number>(0)

  let eventSource: EventSource | null = null
  let retryCount = 0
  let reconnectTimer: ReturnType<typeof setTimeout> | null = null
  let manualDisconnect = false

  const fullUrl = `${url}?incidentId=${encodeURIComponent(incidentId)}`

  const getBackoffDelay = (): number => {
    const delay = initialBackoffMs * Math.pow(2, retryCount)
    return Math.min(delay, maxBackoffMs)
  }

  const cleanup = (): void => {
    if (eventSource) {
      eventSource.close()
      eventSource = null
    }
    if (reconnectTimer) {
      clearTimeout(reconnectTimer)
      reconnectTimer = null
    }
  }

  const scheduleReconnect = (): void => {
    if (reconnectTimer || manualDisconnect) return
    const delay = getBackoffDelay()
    retryCount++
    reconnectTimer = setTimeout(() => {
      reconnectTimer = null
      createEventSource()
    }, delay)
  }

  const createEventSource = (): void => {
    if (eventSource) return

    manualDisconnect = false
    connectionStatus.value = 'connecting'

    try {
      eventSource = new EventSource(fullUrl)
    } catch (err) {
      connectionStatus.value = 'error'
      lastEvent.value = { type: 'error', data: { message: `Failed to create EventSource: ${err}` } }
      eventTimestamp.value = Date.now()
      scheduleReconnect()
      return
    }

    eventSource.onopen = () => {
      connectionStatus.value = 'connected'
      retryCount = 0
    }

    eventSource.addEventListener('pr-status-update', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data)
        lastEvent.value = { type: 'pr-status-update', data }
        eventTimestamp.value = Date.now()
      } catch { /* ignore malformed */ }
    })

    eventSource.addEventListener('pr-created', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data)
        lastEvent.value = { type: 'pr-created', data }
        eventTimestamp.value = Date.now()
      } catch { /* ignore */ }
    })

    eventSource.addEventListener('ci-status-update', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data)
        lastEvent.value = { type: 'ci-status-update', data }
        eventTimestamp.value = Date.now()
      } catch { /* ignore */ }
    })

    eventSource.addEventListener('policy-status-update', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data)
        lastEvent.value = { type: 'policy-status-update', data }
        eventTimestamp.value = Date.now()
      } catch { /* ignore */ }
    })

    eventSource.addEventListener('pr-merged', (e: MessageEvent) => {
      try {
        const data = JSON.parse(e.data)
        lastEvent.value = { type: 'pr-merged', data }
        eventTimestamp.value = Date.now()
      } catch { /* ignore */ }
    })

    eventSource.onerror = () => {
      connectionStatus.value = 'error'
      eventTimestamp.value = Date.now()
      cleanup()
      if (!manualDisconnect) {
        scheduleReconnect()
      }
    }
  }

  const connect = (): void => {
    manualDisconnect = false
    if (!eventSource) {
      createEventSource()
    }
  }

  const disconnect = (): void => {
    manualDisconnect = true
    cleanup()
    connectionStatus.value = 'disconnected'
  }

  onMounted(() => {
    connect()
  })

  onBeforeUnmount(() => {
    disconnect()
  })

  return {
    connectionStatus,
    lastEvent,
    eventTimestamp,
    connect,
    disconnect,
  }
}


