// GITOPS-01: PRPreviewModal
// Modal dialog showing PR changes before creation
// WCAG 2.1: role="dialog", aria-modal="true", focus trapping, Escape to close
// =============================================================================

import { defineComponent, ref, watch, computed, onMounted, onBeforeUnmount, nextTick, type PropType } from 'vue'
import type { IncidentSeverity, PRChange } from './types'

export default defineComponent({
  name: 'PRPreviewModal',
  props: {
    show: { type: Boolean, required: true },
    incidentId: { type: String, required: true },
    severity: { type: String as PropType<IncidentSeverity>, required: true },
    runbookRef: { type: String, required: true },
    targetBranch: { type: String, required: true },
    changes: { type: Array as PropType<PRChange[]>, required: true },
    prTitle: { type: String, required: true },
    prDescription: { type: String, required: true },
    onConfirm: { type: Function as PropType<() => void>, required: true },
    onCancel: { type: Function as PropType<() => void>, required: true },
    onEditDescription: { type: Function as PropType<(val: string) => void>, default: () => {} },
    isLoading: { type: Boolean, default: false },
  },
  setup(props) {
    const localDescription = ref(props.prDescription)
    const expandedDiffs = ref<boolean[]>(props.changes.map(() => false))
    const modalRef = ref<HTMLDivElement | null>(null)
    let lastFocused: HTMLElement | null = null

    watch(() => props.prDescription, (v) => { localDescription.value = v })
    watch(() => props.changes, (v) => { expandedDiffs.value = v.map(() => false) })

    const focusableSelector = 'a[href], button:not([disabled]), textarea, input, select, [tabindex]:not([tabindex="-1"])'

    const getFocusable = (): HTMLElement[] => {
      if (!modalRef.value) return []
      return Array.from(modalRef.value.querySelectorAll<HTMLElement>(focusableSelector))
    }

    const trapFocus = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        props.onCancel()
        return
      }
      if (e.key !== 'Tab') return
      const elements = getFocusable()
      if (elements.length < 2) return
      if (e.shiftKey && document.activeElement === elements[0]) {
        e.preventDefault()
        elements[elements.length - 1].focus()
      } else if (!e.shiftKey && document.activeElement === elements[elements.length - 1]) {
        e.preventDefault()
        elements[0].focus()
      }
    }

    watch(() => props.show, async (show) => {
      if (show) {
        lastFocused = document.activeElement as HTMLElement
        await nextTick()
        const elements = getFocusable()
        if (elements.length > 0) elements[0].focus()
      } else if (lastFocused) {
        lastFocused.focus()
      }
    })

    onMounted(() => document.addEventListener('keydown', trapFocus))
    onBeforeUnmount(() => document.removeEventListener('keydown', trapFocus))

