// =============================================================================
// GITOPS-01: CIFailureAlert
// Molecular component - CI failure alert with Fix & Retry button
// WCAG 2.1: role="alert", aria-live="assertive", focus management
// =============================================================================

import { defineComponent, ref, computed, type PropType } from 'vue'
import type { CIFailureDetail } from './types'

export default defineComponent({
  name: 'CIFailureAlert',
  props: {
    incidentId: { type: String, required: true },
    prNumber: { type: [Number, null] as PropType<number | null>, default: null },
    failureMessage: { type: String, required: true },
    failureDetails: { type: Array as PropType<CIFailureDetail[]>, required: true },
    onFixAndRetry: { type: Function as PropType<() => Promise<void>>, required: true },
    onDismiss: { type: Function as PropType<() => void>, required: true },
  },
  setup(props) {
    const isExpanded = ref(false)
    const isFixing = ref(false)
    const detailsId = `ci-details-${props.incidentId}`

    const failedChecks = computed(() => props.failureDetails.filter(d => d.status === 'failed'))

    const handleFixAndRetry = async () => {
      if (isFixing.value) return
      isFixing.value = true
      try {
        await props.onFixAndRetry()
      } finally {
        isFixing.value = false
      }
    }

    return () => (
      <div
        role="alert"
        aria-live="assertive"
        data-testid="ci-failure-alert"
        class="border-2 border-red-500 bg-red-50 dark:bg-red-900/20 dark:border-red-400 rounded-lg p-4 shadow-md relative"
