            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <h2 class="text-lg font-semibold text-red-800 dark:text-red-200">CI Checks Failed</h2>
        </div>

        {/* Message */}
        <p class="text-sm text-red-700 dark:text-red-300 mb-3">{props.failureMessage}</p>

        {/* Expandable details */}
        {failedChecks.value.length > 0 && (
          <div class="mb-4">
            <button
              type="button"
              data-testid="ci-failure-expand"
              class="inline-flex items-center text-sm font-medium text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-200 focus:outline-none focus:ring-2 focus:ring-red-400 rounded"
              onClick={() => { isExpanded.value = !isExpanded.value }}
              aria-expanded={isExpanded.value}
              aria-controls={detailsId}
            >
              <svg class={`w-4 h-4 mr-1 transition-transform ${isExpanded.value ? 'rotate-90' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7" />
              </svg>
              {isExpanded.value ? 'Hide details' : `Show details (${failedChecks.value.length} failed)`}
            </button>
            <div id={detailsId} role="group" class={`mt-2 space-y-2 ${isExpanded.value ? 'block' : 'hidden'}`}>
              <ul class="space-y-1">
                {failedChecks.value.map((detail, idx) => (
                  <li key={idx} class="flex items-center gap-2 text-sm text-red-700 dark:text-red-300">
                    <svg class="w-4 h-4 text-red-500 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20" aria-hidden="true">
                      <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clip-rule="evenodd" />
                    </svg>
                    <span class="flex-1">{detail.check}</span>
                    {detail.logUrl && (
                      <a href={detail.logUrl} target="_blank" rel="noopener noreferrer" data-testid={`ci-failure-log-link-${idx}`} class="text-blue-600 dark:text-blue-400 underline hover:text-blue-800 dark:hover:text-blue-200 focus:outline-none focus:ring-2 focus:ring-blue-400 rounded">Log</a>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {/* Actions */}
        <div class="flex items-center gap-3 flex-wrap">
          <button
            type="button"
            data-testid="ci-fix-and-retry-button"
            class="inline-flex items-center px-4 py-2 bg-red-600 hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-400 focus:ring-offset-2 dark:focus:ring-offset-gray-900 text-white font-medium rounded-md disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            onClick={handleFixAndRetry}
            disabled={isFixing.value}
          >
            {isFixing.value && (
              <svg class="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" aria-hidden="true">
                <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4" />
                <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
              </svg>
            )}
            {isFixing.value ? 'Fixing...' : 'Fix & Retry'}
          </button>
          <button
            type="button"
            data-testid="ci-escalate-button"
            class="text-sm font-medium text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-200 underline focus:outline-none focus:ring-2 focus:ring-red-400 rounded"
          >Escalate</button>
        </div>

        {/* Screen reader context */}
        {props.prNumber !== null && (
          <span class="sr-only">Associated pull request #{props.prNumber}</span>
        )}
      </div>
    )
  },
})


