// =============================================================================
// GITOPS-01: PRTimelineWidget
// Organism component - live vertical timeline of PR steps
// WCAG 2.1: role="list", aria-label, aria-live region for updates
// =============================================================================

import { defineComponent, ref, computed, watch, type PropType } from 'vue'
import TimelineStep from './TimelineStep'
import PRStatusBadge from './PRStatusBadge'
import type { TimelineStepData, Phase } from './types'
import type { PRStatus } from './PRStatusBadge'

export default defineComponent({
  name: 'PRTimelineWidget',
  props: {
    steps: { type: Array as PropType<TimelineStepData[]>, required: true },
    currentPhase: { type: String as PropType<Phase>, required: true },
    prNumber: { type: [Number, null] as PropType<number | null>, default: null },
    prUrl: { type: [String, null] as PropType<string | null>, default: null },
    connectionStatus: { type: String as PropType<'connecting' | 'connected' | 'disconnected' | 'error'>, default: 'disconnected' },
    onCancel: { type: Function as PropType<() => void>, required: true },
  },
  setup(props) {
    const showCancelDialog = ref(false)

    const phaseToPRStatus = computed<PRStatus>(() => {
      switch (props.currentPhase) {
        case 'creating':
        case 'created': return 'draft'
        case 'ci-running': return 'ci-in-progress'
        case 'ci-failed': return 'ci-failed'
        case 'policy-check': return 'policy-check'
        case 'awaiting-approval': return 'approvals-pending'
        case 'merged': return 'merged'
        case 'cancelled': return 'cancelled'
        default: return 'draft'
      }
    })

    const ariaLiveMessage = ref('')
    watch(() => props.currentPhase, (phase) => {
      const msgs: Record<string, string> = {
        creating: 'Creating pull request',
        created: 'Pull request created',
        'ci-running': 'CI checks running',
        'ci-failed': 'CI checks failed',
        'policy-check': 'Policy check in progress',
        'awaiting-approval': 'Awaiting approvals',
        merged: 'Pull request merged',
        cancelled: 'Pull request cancelled',
      }
      ariaLiveMessage.value = msgs[phase] || `Status: ${phase}`
    }, { immediate: true })

    const connectionDot = computed(() => {
      switch (props.connectionStatus) {
        case 'connected':
          return <span class="w-2 h-2 rounded-full bg-green-500 inline-block" aria-label="Connected" />
        case 'connecting':
          return <span class="w-2 h-2 rounded-full bg-yellow-500 inline-block animate-pulse" aria-label="Connecting" />
        case 'error':
          return <span class="w-2 h-2 rounded-full bg-red-500 inline-block" aria-label="Connection error" />
        default:
          return <span class="w-2 h-2 rounded-full bg-gray-400 inline-block" aria-label="Disconnected" />
      }
    })

    return () => (
      <div data-testid="pr-timeline-widget" class="rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 shadow-sm">
        {/* Header */}
        <div class="flex items-center justify-between px-4 py-3 border-b border-gray-200 dark:border-gray-700">
          <div class="flex items-center gap-3">
            <h2 class="text-lg font-semibold text-gray-900 dark:text-gray-100">Pull Request Timeline</h2>
            {props.prNumber && (
              props.prUrl ? (
                <a href={props.prUrl} target="_blank" rel="noopener noreferrer" class="text-blue-600 dark:text-blue-400 hover:underline text-sm" aria-label={`PR #${props.prNumber}`} data-testid="pr-number-link">PR #{props.prNumber}</a>
              ) : (
                <span class="text-gray-500 dark:text-gray-400 text-sm" data-testid="pr-number-text">PR #{props.prNumber}</span>
              )
            )}
            <PRStatusBadge status={phaseToPRStatus.value} />
          </div>
          <div class="flex items-center gap-2">
            {connectionDot.value}
            <span class="text-xs text-gray-500 dark:text-gray-400 capitalize">{props.connectionStatus}</span>
          </div>
        </div>

        {/* Timeline steps */}
        <ul role="list" aria-label="Pull Request Timeline" class="px-4 py-3">
          {props.steps.map((step, idx) => (
            <TimelineStep
              key={step.key}
              status={step.status}
              label={step.label}
              timestamp={step.timestamp}
              description={step.description}
              isLast={idx === props.steps.length - 1}
              ariaSetSize={props.steps.length}
              ariaPosInSet={idx + 1}
            />
          ))}
        </ul>

        {/* Cancel button */}
        <div class="px-4 py-3 border-t border-gray-200 dark:border-gray-700">
          <button
            type="button"
            class="inline-flex items-center px-3 py-1.5 text-sm font-medium text-red-700 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-md hover:bg-red-100 dark:hover:bg-red-900/40 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800"
            onClick={() => { showCancelDialog.value = true }}
            data-testid="cancel-pr-button"
            aria-label="Cancel Pull Request"
          >Cancel PR</button>
        </div>

        {/* aria-live region */}
        <div aria-live="polite" aria-atomic="true" class="sr-only" data-testid="pr-timeline-live-region">
          {ariaLiveMessage.value}
        </div>

        {/* Cancel confirmation dialog */}
        {showCancelDialog.value && (
          <div
            class="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
            role="dialog"
            aria-modal="true"
            aria-labelledby="cancel-dialog-title"
            data-testid="cancel-dialog-overlay"
            onClick={() => { showCancelDialog.value = false }}
          >
            <div
              class="bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 max-w-sm mx-4"
              onClick={(e: MouseEvent) => e.stopPropagation()}
              data-testid="cancel-dialog-content"
            >
              <h3 id="cancel-dialog-title" class="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-2">Cancel Pull Request</h3>
              <p class="text-sm text-gray-600 dark:text-gray-400 mb-6">Are you sure you want to cancel this pull request? This action cannot be undone.</p>
              <div class="flex justify-end gap-3">
                <button
                  type="button"
                  class="px-4 py-2 text-sm font-medium text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 focus:outline-none focus:ring-2 focus:ring-gray-400"
                  onClick={() => { showCancelDialog.value = false }}
                  data-testid="cancel-dialog-no"
                >No, keep it</button>
                <button
                  type="button"
                  class="px-4 py-2 text-sm font-medium text-white bg-red-600 rounded-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500"
                  onClick={() => {
                    showCancelDialog.value = false
                    props.onCancel()
                  }}
                  data-testid="cancel-dialog-yes"
                >Yes, cancel PR</button>
              </div>
            </div>
          </div>
        )}
      </div>
    )
  },
})


