    const showCancelDialog = ref(false)
    const isLoading = ref(false)
    const editableDescription = ref(props.prDescription)

    // ---- Computed ----
    const steps = computed(() => deriveTimelineSteps(currentPhase.value))

    // ---- SSE Integration ----
    const { connectionStatus, lastEvent } = useGitOpsEventStream({
      incidentId: props.incidentId,
    })

    watch(lastEvent, (event) => {
      if (!event) return
      switch (event.type) {
        case 'pr-created':
          prData.value = event.data as unknown as PRData
          currentPhase.value = 'created'
          break
        case 'ci-status-update': {
          const ciData = event.data as { status?: string }
          if (ciData.status === 'running') currentPhase.value = 'ci-running'
          else if (ciData.status === 'failure') {
            ciFailure.value = {
              message: 'CI pipeline failed',
              failureDetails: [],
              prNumber: prData.value?.prNumber ?? null,
            }
            currentPhase.value = 'ci-failed'
          }
          break
        }
        case 'policy-status-update':
          currentPhase.value = 'policy-check'
          break
        case 'pr-status-update': {
          const st = event.data as { status?: string }
          if (st.status === 'awaiting-approval') currentPhase.value = 'awaiting-approval'
          break
        }
        case 'pr-merged':
          currentPhase.value = 'merged'
          break
        case 'error':
          currentPhase.value = 'failed'
          break
      }
    })

    // ---- Actions ----
    const openPreview = () => {
      showPreview.value = true
      currentPhase.value = 'preview'
    }

    const closePreview = () => {
      showPreview.value = false
      currentPhase.value = 'idle'
    }

    const confirmCreatePR = async () => {
      isLoading.value = true
      currentPhase.value = 'creating'
      try {
        const result = await props.onTriggerRemediation()
        prData.value = result
        currentPhase.value = 'created'
        showPreview.value = false
      } catch {
        currentPhase.value = 'failed'
      } finally {
        isLoading.value = false
      }
    }

    const confirmCancel = () => {
      showCancelDialog.value = false
      props.onCancelRemediation()
      currentPhase.value = 'cancelled'
      showPreview.value = false
    }

    const handleFixAndRetry = async () => {
      currentPhase.value = 'ci-running'
      ciFailure.value = null
      try {
        await props.onFixAndRetry()
        currentPhase.value = 'policy-check'
      } catch {
        ciFailure.value = {
          message: 'Retry attempt failed',
          failureDetails: [],
          prNumber: prData.value?.prNumber ?? null,
        }
        currentPhase.value = 'ci-failed'
      }
    }

    const handleDismiss = () => {
      ciFailure.value = null
      currentPhase.value = 'cancelled'
    }

    // ---- Accessibility - live region ----
    const announcer = ref('')
    watch(currentPhase, (phase) => {
      const messages: Record<Phase, string> = {
        idle: 'Remediation idle',
        preview: 'Reviewing pull request',
        creating: 'Creating pull request',
        created: 'Pull request created',
        'ci-running': 'CI checks running',
        'ci-failed': 'CI checks failed',
        'policy-check': 'Policy check in progress',
        'awaiting-approval': 'Awaiting approvals',
        merged: 'Pull request merged',
        failed: 'Remediation failed',
        cancelled: 'Remediation cancelled',
      }
      announcer.value = messages[phase] || phase
    }, { immediate: true })

    // ---- Connection badge ----
    const connectionBadge = computed(() => {
      const config: Record<string, { label: string; class: string }> = {
        connected: { label: 'Connected', class: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' },
        connecting: { label: 'Connecting...', class: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200' },
        disconnected: { label: 'Disconnected', class: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200' },
        error: { label: 'Connection Error', class: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200' },
      }
      return config[connectionStatus.value] || config.disconnected
    })

    // ---- Phase indicator ----
    const phaseIndicator = computed(() => {
      const indicators: Record<Phase, { icon: string; text: string; class: string }> = {
        idle: { icon: '⏸', text: 'Idle', class: 'text-gray-600 dark:text-gray-400' },
        preview: { icon: '👁', text: 'Previewing', class: 'text-blue-600 dark:text-blue-400' },
        creating: { icon: '⏳', text: 'Creating PR...', class: 'text-blue-600 dark:text-blue-400' },
        created: { icon: '✅', text: 'PR Created', class: 'text-green-600 dark:text-green-400' },
        'ci-running': { icon: '🔄', text: 'CI Running', class: 'text-blue-600 dark:text-blue-400' },
        'ci-failed': { icon: '❌', text: 'CI Failed', class: 'text-red-600 dark:text-red-400' },
        'policy-check': { icon: '📋', text: 'Policy Check', class: 'text-yellow-600 dark:text-yellow-400' },
        'awaiting-approval': { icon: '⏳', text: 'Awaiting Approval', class: 'text-purple-600 dark:text-purple-400' },
        merged: { icon: '🔀', text: 'Merged', class: 'text-green-600 dark:text-green-400' },
        failed: { icon: '💥', text: 'Failed', class: 'text-red-600 dark:text-red-400' },
        cancelled: { icon: '🚫', text: 'Cancelled', class: 'text-gray-600 dark:text-gray-400' },
      }
      return indicators[currentPhase.value]
    })

    const nonIdlePhases: Phase[] = ['preview', 'creating', 'created', 'ci-running', 'ci-failed', 'policy-check', 'awaiting-approval', 'merged']
    const showFixedCancel = computed(() => nonIdlePhases.includes(currentPhase.value))

    return () => (
      <div data-testid="gitops-pr-panel" class="relative">
        {/* Screen reader announcer */}
        <div aria-live="polite" aria-atomic="true" class="sr-only" role="status" data-testid="gitops-panel-announcer">
