              connectionStatus={connectionStatus.value}
              onCancel={() => { showCancelDialog.value = true }}
            />
          </div>
        )}

        {/* ===== PHASE: FAILED ===== */}
        {currentPhase.value === 'failed' && (
          <div data-testid="failed-state" class="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-6">
            <div class="flex items-center gap-3 mb-3">
