        {/* ===== PHASE: CANCELLED ===== */}
        {currentPhase.value === 'cancelled' && (
          <div data-testid="cancelled-state" class="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-6">
