              <svg class="h-6 w-6 text-yellow-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m-2-2a4 4 0 100-8 4 4 0 000 8z" />
              </svg>
              <h4 class="text-lg font-semibold text-yellow-800 dark:text-yellow-200">Remediation Cancelled</h4>
            </div>
            <p class="text-sm text-yellow-700 dark:text-yellow-300">
              The remediation for incident {props.incidentId} was cancelled. No further automated actions will be taken.
            </p>
            <button
              type="button"
              data-testid="restart-after-cancel"
              class="mt-4 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors"
              onClick={() => { currentPhase.value = 'idle' }}
            >Start New Remediation</button>
          </div>
        )}
      </div>
    )
  },
})


